export function getLegalContent(locale: Locale): LegalLocale {
  const source = locale === "en" ? en : translations[locale];
  const inject = (value: string) => value
    .replaceAll("[LEGAL_NAME]", legalConfig.legalName)
    .replaceAll("[CONTACT_EMAIL]", legalConfig.contactEmail)
    .replaceAll("[LEGAL_CONTACT_DETAILS]", legalConfig.legalContactDetails);
  return {
    ...source,
    documents: Object.fromEntries(Object.entries(source.documents).map(([id, document]) => [id, {
      ...document,
      introduction: inject(document.introduction),
      description: inject(document.description),
      sections: document.sections.map(section => ({
        ...section,
        paragraphs: section.paragraphs.map(inject),
        bullets: section.bullets?.map(inject),
      })),
    }])) as Record<LegalDocumentId, Document>,
  };
}
